import{_ as a,o as n,c as t,a5 as e}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"24. Strings as Character Arrays","description":"The Little Book of C — 24. Strings as Character Arrays","frontmatter":{"title":"24. Strings as Character Arrays","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working with Memory"],"description":"The Little Book of C — 24. Strings as Character Arrays","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":24,"sidebarWeight":24,"lang":"en-US","alternateEn":"/posts/c教程/en-US/03-Working with Memory/024-Strings as Character Arrays","alternateZh":"/posts/c教程/zh-CN/03-内存/024-Strings as Character Arrays"},"headers":[],"relativePath":"posts/c教程/en-US/03-Working with Memory/024-Strings as Character Arrays.md","filePath":"posts/c教程/en-US/03-Working with Memory/024-Strings as Character Arrays.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/03-Working with Memory/024-Strings as Character Arrays.md"};function o(r,s,p,l,c,d){return n(),t("div",null,[...s[0]||(s[0]=[e(`<p>[中文版本](/posts/c教程/zh-CN/03-内存/024-Strings as Character Arrays)</p><p>In C, a string is simply an array of characters ending with a special null character<code>&#39;\\0&#39;</code>. Unlike higher-level languages, C doesn’t have a built-in string type, just arrays and pointers. This simplicity gives you full control over text data but also demands care: every string operation must respect memory limits and null terminators.</p><h4 id="how-strings-work" tabindex="-1">How Strings Work <a class="header-anchor" href="#how-strings-work" aria-label="Permalink to &quot;How Strings Work&quot;">​</a></h4><p>A string like<code>&quot;Hello&quot;</code> in C is represented internally as:</p><table tabindex="0"><thead><tr><th>Character</th><th>H</th><th>e</th><th>l</th><th>l</th><th>o</th><th><code>\\0</code></th></tr></thead><tbody><tr><td>Index</td><td>0</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td></tr></tbody></table><p>The<code>&#39;\\0&#39;</code>(ASCII 0) marks the end of the string, it’s how functions like<code>printf</code> or<code>strlen</code> know where to stop.</p><h4 id="declaring-strings" tabindex="-1">Declaring Strings <a class="header-anchor" href="#declaring-strings" aria-label="Permalink to &quot;Declaring Strings&quot;">​</a></h4><p>There are two common ways to declare strings:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char greeting1[] = &quot;Hello&quot;;        // automatic null terminator</span></span>
<span class="line"><span>char greeting2[6] = {&#39;H&#39;,&#39;e&#39;,&#39;l&#39;,&#39;l&#39;,&#39;o&#39;,&#39;\\0&#39;}; // explicit</span></span>
<span class="line"><span>char *greeting3 = &quot;Hello&quot;;         // pointer to string literal</span></span></code></pre></div><p><code>greeting1</code> is a mutable array you can modify.<code>greeting3</code> points to a read-only string literal stored in memory, modifying it causes undefined behavior.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>Here’s a complete example that explores string declarations, iteration, and basic operations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char msg[] = &quot;C language&quot;;</span></span>
<span class="line"><span>    char *ptr = msg; // pointer to the first character</span></span>
<span class="line"><span>    printf(&quot;String: %s\\n&quot;, msg);</span></span>
<span class="line"><span>    printf(&quot;Length: %zu\\n&quot;, strlen(msg));</span></span>
<span class="line"><span>    printf(&quot;\\nCharacters one by one:\\n&quot;);</span></span>
<span class="line"><span>    for (int i = 0; msg[i] != &#39;\\0&#39;; i++) {</span></span>
<span class="line"><span>        printf(&quot;msg[%d] = %c (address: %p)\\n&quot;, i, msg[i], (void *)&amp;msg[i]);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;\\nAccess via pointer arithmetic:\\n&quot;);</span></span>
<span class="line"><span>    for (int i = 0; *(ptr + i) != &#39;\\0&#39;; i++) {</span></span>
<span class="line"><span>        printf(&quot;*(ptr + %d) = %c\\n&quot;, i, *(ptr + i));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    // Modify string safely</span></span>
<span class="line"><span>    msg[0] = &#39;C&#39;;</span></span>
<span class="line"><span>    msg[1] = &#39;+&#39;;</span></span>
<span class="line"><span>    printf(&quot;\\nModified string: %s\\n&quot;, msg);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc strings_demo.c -o strings_demo</span></span>
<span class="line"><span>./strings_demo</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>String: C language</span></span>
<span class="line"><span>Length: 10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Characters one by one:</span></span>
<span class="line"><span>msg[0] = C (address: 0x7ffd29c4a0a0)</span></span>
<span class="line"><span>msg[1] =   (address: 0x7ffd29c4a0a1)</span></span>
<span class="line"><span>msg[2] = l (address: 0x7ffd29c4a0a2)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Access via pointer arithmetic:</span></span>
<span class="line"><span>*(ptr + 0) = C</span></span>
<span class="line"><span>*(ptr + 1) =  </span></span>
<span class="line"><span>*(ptr + 2) = l</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Modified string: C+anguage</span></span></code></pre></div><h4 id="common-string-operations" tabindex="-1">Common String Operations <a class="header-anchor" href="#common-string-operations" aria-label="Permalink to &quot;Common String Operations&quot;">​</a></h4><p>C provides several standard functions in<code>&lt;string.h&gt;</code>:</p><table tabindex="0"><thead><tr><th>Function</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>strlen(s)</code></td><td>Get string length (excluding<code>\\0</code>)</td><td><code>strlen(&quot;Hi&quot;) == 2</code></td></tr><tr><td><code>strcpy(dest, src)</code></td><td>Copy string</td><td><code>strcpy(name, &quot;Bob&quot;);</code></td></tr><tr><td><code>strcat(dest, src)</code></td><td>Concatenate strings</td><td><code>strcat(full, last);</code></td></tr><tr><td><code>strcmp(a, b)</code></td><td>Compare strings (<code>0</code> if equal)</td><td><code>strcmp(&quot;a&quot;,&quot;b&quot;)</code></td></tr><tr><td><code>strchr(s, c)</code></td><td>Find first occurrence of character</td><td><code>strchr(word, &#39;a&#39;)</code></td></tr><tr><td><code>strstr(s, sub)</code></td><td>Find substring</td><td><code>strstr(text, &quot;find&quot;)</code></td></tr></tbody></table><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char a[20] = &quot;Hello, &quot;;</span></span>
<span class="line"><span>char b[] = &quot;World!&quot;;</span></span>
<span class="line"><span>strcat(a, b);</span></span>
<span class="line"><span>printf(&quot;%s\\n&quot;, a); // &quot;Hello, World!&quot;</span></span></code></pre></div><h4 id="pointers-and-strings" tabindex="-1">Pointers and Strings <a class="header-anchor" href="#pointers-and-strings" aria-label="Permalink to &quot;Pointers and Strings&quot;">​</a></h4><p>Because a string’s name decays into a pointer, you can pass strings directly to functions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void greet(const char *name) {</span></span>
<span class="line"><span>    printf(&quot;Hello, %s!\\n&quot;, name);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    greet(&quot;C Learner&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>const char *</code> prevents accidental modification of the string literal.</p><h4 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h4><p>Forgetting<code>&#39;\\0&#39;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char word[4] = {&#39;T&#39;,&#39;e&#39;,&#39;s&#39;,&#39;t&#39;}; // missing terminator, unsafe</span></span></code></pre></div><p>Buffer overflows: Copying more characters than fit in the destination buffer leads to undefined behavior.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char dest[5];</span></span>
<span class="line"><span>strcpy(dest, &quot;Too long!&quot;); // dangerous</span></span></code></pre></div><p>Modifying string literals:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char *s = &quot;Hello&quot;;</span></span>
<span class="line"><span>s[0] = &#39;Y&#39;; // crash or undefined behavior</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Strings are the foundation of text processing, file handling, and user interfaces in C. Because they’re just arrays of characters, understanding strings forces you to think about:</p><ul><li>Memory layout</li><li>Null termination</li><li>Buffer size and safety</li></ul><p>Once you internalize how C handles text at the byte level, you’ll be ready to build real parsers, file readers, and command-line tools.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a function<code>void reverse(char *s)</code> that reverses a string in place.</li><li>Implement your own version of<code>strlen</code>.</li><li>Create a program that counts vowels in a string.</li><li>Concatenate two user-input strings using<code>strcat</code>.</li><li>Experiment by printing a string without<code>&#39;\\0&#39;</code>, observe what happens.</li></ol><p>Strings in C are both elegant and dangerous, a true test of precision. Once you master them, you’ll understand how text truly exists in memory, one byte at a time.</p>`,40)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
